# Include this selected role once inside an owned Nginx http block.
log_format linux_toy '$status $request upstream=$upstream_status app=$upstream_addr';
server {
    listen 127.0.0.1:8080;
    server_name _;
    access_log logs/proxy-access.log linux_toy;
    error_log logs/proxy-error.log info;
    location / {
        proxy_http_version 1.1;
        proxy_set_header Connection close;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $remote_addr;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_connect_timeout 1s;
        proxy_read_timeout 3s;
        proxy_pass http://127.0.0.1:8081;
    }
}

